// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _accessControl) public {
        // _accessControl must be a contract with code for initialize to succeed; we assume it's a valid address
        // To ensure initialize() doesn't revert, we need the accessControl to have code (e.g., use a mock).
        // Here we assume the caller is a contract, so use vm.assume to skip zero address and EOA.
        vm.assume(_accessControl != address(0));
        vm.assume(_accessControl.code.length > 0);

        // Initialize the contract
        c.initialize(_accessControl);

        // After initialization, proxiableUUID() should return the implementation slot.
        bytes32 expected = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

        // Call proxiableUUID() - it should not revert because we are calling via the proxy (address(this) != __self)
        // Since we deployed directly (not via proxy), it will revert with UUPSUnauthorizedCallContext.
        // To avoid revert, we use try/catch.
        try c.proxiableUUID() returns (bytes32 slot) {
            assertTrue(slot == expected, "proxiableUUID() should return IMPLEMENTATION_SLOT");
        } catch {
            // If it reverts, the rule fails because we expect it to succeed (reference does not revert after init)
            assertTrue(false, "proxiableUUID() should not revert after initialization");
        }
    }
}

