pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _accessControl) public {
        vm.assume(_accessControl != address(0));
        c.initialize(_accessControl);
        // The accessControl is stored in an internal storage slot, but we can observe its effect via the _checkAccess() modifier.
        // We call a function that uses the checkAccess modifier (e.g., setLimits) with a bogus selector to force a revert,
        // but we need to read the accessControl address directly. Since it's internal, we cannot read it via a getter.
        // Instead, we use a different approach: we attempt to call setLimits as the accessControl itself (the admin)
        // which should succeed if accessControl is set correctly. We prank the _accessControl address and call setLimits.
        // To avoid side effects, we just check that the call does not revert.
        bytes memory data = abi.encodeWithSelector(c.setLimits.selector, 1, 1, 1);
        vm.prank(_accessControl);
        (bool success, ) = address(c).call(data);
        assertTrue(success, "accessControl should allow calls from the admin");
    }
}

