pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl) public {
        vm.assume(accessControl != address(0));
        // create a mock accessControl that returns true for checkAccess
        // We'll deploy a simple contract that implements IAccessControl
        // For simplicity, we just check that the accessControl is set by calling initialize
        // and then checking that the accessControl address stored in the contract is the one we passed
        // But since we cannot read internal storage, we can use a different approach:
        // We can call a function that uses checkAccess modifier (e.g., setSlopes) and see if it reverts with AccessDenied
        // If accessControl is set properly, a call to setSlopes with a valid selector should not revert with AccessDenied
        // But setSlopes also requires the caller to have access, which depends on the mock contract.
        // Instead, we can check that after initialize, the contract's accessControl slot is set to the passed address
        // by using a dedicated getter if one exists. Since there isn't, we can test indirectly:
        // We'll call initialize with the given accessControl, then call a function that uses checkAccess
        // and expect it to revert with AccessDenied (since the mock will return false).
        // Actually, we need a mock that returns true for a specific selector. Let's create a minimal implementation.
        // For simplicity, we can use vm.etch to set a minimal contract that returns true.
        // But to avoid complexity, we can just check that the contract's accessControl variable is set by comparing the value
        // via a getter if we had one. Since we don't, we can't directly test that.
        // The property should be: after initialize, the contract's accessControl is set.
        // We can check by calling a function that uses the accessControl modifier and see if it reverts with AccessDenied.
        // If accessControl is not set (zero address), the call to IAccessControl.checkAccess will revert.
        // So we can do:
        c.initialize(accessControl);
        // Now try to call a function that uses checkAccess. Use vm.prank to set caller.
        // We'll try to call setSlopes with the selector of setSlopes.
        // Since accessControl is a random address, it likely doesn't implement checkAccess properly, so call will revert.
        // Actually, we need to ensure that the accessControl address is set to the passed parameter.
        // We can check by calling checkAccess on the IAccessControl interface? No, we cannot because we don't have a reference to it.
        // Instead, we can call a public view function that returns the accessControl address if it exists. It doesn't.
        // So we need another approach: we can test that after initialize, the contract's behavior changes.
        // For the reference, initialize sets accessControl. For the mutant, it doesn't.
        // We can check by calling a function that uses checkAccess and see if it reverts with AccessDenied.
        // For the reference, if accessControl is random address, checkAccess will probably revert or return false, causing AccessDenied.
        // For the mutant, accessControl is zero address, so checkAccess will revert because it tries to call a contract at address(0).
        // Both will revert but with different reasons. But we cannot check revert reason easily.
        // A better property: after initialize, if we call a function that uses checkAccess, it should not revert with AccessDenied
        // if the accessControl returns true. But we control the accessControl address; we can deploy a mock that returns true.
        // Let's deploy a simple contract that implements checkAccess to return true.
        MockAccessControl mock = new MockAccessControl();
        c.initialize(address(mock));
        // Now try to call setSlopes via vm.prank with a random caller.
        // The mock returns true, so the call should succeed if accessControl is set.
        // For the mutant, the accessControl is zero, so the call to checkAccess will revert (cannot call zero address).
        // So we can check that the call to setSlopes does not revert.
        // But setSlopes requires valid arguments; let's provide valid ones.
        // For the reference, the call should succeed (since mock returns true).
        // For the mutant, it will revert because it tries to call address(0).
        // So we can assert that the call succeeds.
        vm.prank(address(0xdead));
        // Provide dummy slope data
        C.SlopeData memory slopes = C.SlopeData({kink: 1e27/2, slope0: 1e18, slope1: 2e18});
        // This call will revert in mutant, succeed in reference.
        bool success = address(this).call(abi.encodeWithSelector(c.setSlopes.selector, address(0x123), slopes));
        assertTrue(success, "setSlopes should succeed when accessControl is set");
    }
}

contract MockAccessControl {
    function checkAccess(bytes4, address, address) external view returns (bool) {
        return true;
    }
    function initialize(address) external {}
    function grantAccess(bytes4, address, address) external {}
    function revokeAccess(bytes4, address, address) external {}
    function role(bytes4, address) external pure returns (bytes32) { return bytes32(0); }
}

