contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address vault, address asset) public {
        // Bound inputs to avoid reverted calls due to invalid initialization
        vm.assume(vault != address(0) && asset != address(0));

        // Initialize the contract with a dummy access control address
        vm.assume(vault.code.length > 0); // Ensure vault is a contract
        c.initialize(address(0xdead));

        // Set slopes and limits so _applySlopes can proceed
        // We use arbitrary values that satisfy the invariant checks
        uint256 kink = 0.5e27; // 50%
        c.setSlopes(asset, C.SlopeData({kink: kink, slope0: 1e27, slope1: 1e27}));
        c.setLimits(2e27, 0.5e27, 1e27);

        // First call to rate
        uint256 firstRate = c.rate(vault, asset);

        // Simulate a state change that increases utilization index
        // We can't directly change vault state, but we can call rate again with same params
        // to see if the bug (wrong order of storage updates) causes inconsistency
        uint256 secondRate = c.rate(vault, asset);

        // The bug in M reverses the update order of index and lastUpdate.
        // In correct C, the index is updated before lastUpdate, so the next call sees correct elapsed.
        // In buggy M, lastUpdate is updated first, then index, causing the second call to use wrong elapsed.
        // This can lead to a lower rate in the second call if utilization index increased.
        // Since we have no intervening state change, the correct behavior should give same or higher rate.
        // The bug can cause secondRate to be lower than firstRate.
        assertTrue(secondRate >= firstRate / 2, "Rate decreased unexpectedly due to storage order bug");
    }
}

