        (uint256 prevKink, uint256 prevSlope0, uint256 prevSlope1) = c.slopeData(_asset);
        c.setSlopes(_asset, C.SlopeData({kink: _kink, slope0: _slope0, slope1: _slope1}));
        (uint256 newKink, uint256 newSlope0, uint256 newSlope1) = c.slopeData(_asset);
        assertTrue(newKink != prevKink || newSlope0 != prevSlope0 || newSlope1 != prevSlope1);
    }
}

